import kotlin.properties.Delegates

fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome80 {
    data class Success(val payload: String) : Outcome80()
    data object Failure : Outcome80()
}

fun describe80(outcome: Outcome80): String = when (outcome) {
    is Outcome80.Success -> outcome.payload
    Outcome80.Failure -> "failed"
}
@JvmName("step81")
fun step81(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 19
}
class Counter82 {
    var current: Int by Delegates.observable(26) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
